insert into posts (id, kind, slug, title, excerpt, body, cover, author, published_on) values
  ('ps-9', 'news', 'lich-giao-thang-4', 'Lịch giao xe tháng 4: GS trước, RT sau', 'Ba chiếc Triple Black về tuần đầu. RT trễ một tuần vì kính gió.', 'Ưu tiên khách đã cọc GS. RT hẹn lại sau khi kính về đủ, đừng hứa ngày cứng.', 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1400&q=80', 'Kho xe', '2026-03-28'),
  ('ps-10', 'news', 'mau-racing-red-het', 'Racing Red tạm hết, còn Trophy và Triple Black', 'Khách muốn đỏ: ghi danh đợt sau, đừng giữ xe Trophy để sơn lại.', 'Trophy khác đồ họa và một số ốp. Không đổi màu tại xưởng.', 'https://images.unsplash.com/photo-1449426468159-d96dbf08f19f?auto=format&fit=crop&w=1400&q=80', 'Kho xe', '2026-03-21'),
  ('ps-11', 'news', 'gia-phu-tung-y-suoi', 'Giá yên sưởi và tay nắm sưởi cập nhật', 'Lắp thêm sau bán vẫn được, nhưng chờ hàng khoảng ba tuần.', 'Báo khách trước khi chốt bản tiêu chuẩn nếu họ đi đêm.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1400&q=80', 'Phụ tùng', '2026-03-18'),
  ('ps-12', 'news', 'dao-tao-sales-t4', 'Buổi đào tạo sales thứ Năm tuần này', 'Ôn timeline Triple Black và cách phân biệt Dynamic với Comfort.', 'Mang điện thoại, mở đúng mốc Đợt 2 khi khách hỏi gói.', 'https://images.unsplash.com/photo-1558980664-10e7170b5df2?auto=format&fit=crop&w=1400&q=80', 'Đào tạo', '2026-03-16'),
  ('ps-13', 'news', 'bao-hanh-dau-tien', 'Nhắc khách bảo hành mốc 1.000 km', 'Xe giao tháng 2 đến hạn trong hai tuần tới.', 'Gọi trước, đừng đợi khách tự nhớ. Ghi số máy trong phiếu giao.', 'https://images.unsplash.com/photo-1609630875171-b1321377ee65?auto=format&fit=crop&w=1400&q=80', 'Dịch vụ', '2026-03-10'),
  ('ps-14', 'news', 'non-va-ao-gioi-thieu', 'Nón và áo giới thiệu còn size M, L', 'Hết XL. Đừng hứa tặng áo khi chốt xe cuối tuần.', 'Size S còn hai cái, dành cho khách nữ nếu họ hỏi.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1400&q=80', 'Showroom', '2026-03-05'),
  ('ps-15', 'news', 'thu-cu-gs-cu', 'Thu cũ GS đời trước: quy trình mới', 'Định giá trong ngày nếu xe có sổ và không tai nạn khung.', 'Chụp số khung, số máy, mặt đồng hồ trước khi hẹn thợ.', 'https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1400&q=80', 'Thu cũ', '2026-02-26'),
  ('ps-16', 'news', 'mua-mua-lop', 'Mùa mưa: lốp nào đang có sẵn', 'Lốp đường nhựa về đủ. Lốp gai địa hình phải đặt.', 'Khách GS Trophy hỏi gai: ghi đơn, không tháo lốp xe trưng bày.', 'https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=1400&q=80', 'Phụ tùng', '2026-02-20'),
  ('ps-17', 'tech', 'shiftcam', 'ShiftCam trên boxer 1300', 'Đổi biên dạng cam theo vòng tua. Mô-men sớm, công suất trên tua cao.', 'Giải thích ngắn: dưới 5.000 vòng xe vẫn kéo, không phải đợi nổ vòng.', 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2026-02-12'),
  ('ps-18', 'tech', 'riding-modes', 'Các chế độ lái Rain, Road, Dynamic', 'Rain làm ga dịu và ABS sớm. Dynamic để ga mở hơn.', 'Đèo ướt: khuyên Rain. Đường khô, khách rành: Road là đủ.', 'https://images.unsplash.com/photo-1449426468159-d96dbf08f19f?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2026-02-02'),
  ('ps-19', 'tech', 'dtc', 'Kiểm soát lực kéo DTC', 'Cắt ga khi bánh sau trượt, có tính góc nghiêng.', 'Khác với ABS. DTC lo bánh sau khi mở ga, ABS lo bánh khi bóp phanh.', 'https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2026-01-22'),
  ('ps-20', 'tech', 'abs-pro', 'ABS Pro', 'ABS vẫn hoạt động khi xe đang nghiêng, không chỉ khi thẳng.', 'Câu hay gặp: có ABS Pro thì vẫn phải nhìn đường, không phải phanh muộn hơn.', 'https://images.unsplash.com/photo-1558980664-10e7170b5df2?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2026-01-15'),
  ('ps-21', 'tech', 'led-matrix', 'Đèn pha thích ứng', 'Chùm sáng đổi theo góc lái và xe ngược chiều.', 'Ban đêm đèo: đây là điểm khách để ý hơn công suất.', 'https://images.unsplash.com/photo-1609630875171-b1321377ee65?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2025-12-20'),
  ('ps-22', 'tech', 'ket-noi-dien-thoai', 'Màn hình và kết nối điện thoại', 'Xem bản đồ và nghe gọi trên TFT, không cần gắn giá điện thoại lên ghi-đông.', 'Hướng dẫn khách cài ứng dụng trước ngày giao xe.', 'https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2025-12-08'),
  ('ps-23', 'tech', 'chieu-cao-yen', 'Chiều cao yên và cách chọn', 'Yên thấp, yên tiêu chuẩn, yên comfort đổi được sau.', 'Khách chân ngắn: cho ngồi thử trước khi nói về option.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1400&q=80', 'Kỹ thuật', '2025-11-28'),
  ('ps-24', 'blog', 'sang-da-lat-mot-minh', 'Sài Gòn đi Đà Lạt một mình', '500 km, nghỉ một lần. Road là đủ, không cần Dynamic.', 'Gió lạnh từ Bảo Lộc. Tay nắm sưởi đáng tiền hơn mình nghĩ.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1400&q=80', 'Minh', '2026-03-02'),
  ('ps-25', 'blog', 'cho-vo-cuoi-tuan', 'Chở vợ cuối tuần ra hồ Trị An', 'Bản Comfort. Người sau ngủ gật được một đoạn.', 'Yên rộng thật. Kính để vừa đầu người sau thì người lái hơi nóng.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1400&q=80', 'Hà', '2026-02-18'),
  ('ps-26', 'blog', 'lan-dau-dung-lai', 'Lần đầu đứng lái trên đường đất ngắn', 'Không cần Trophy. Bản tiêu chuẩn qua đoạn đất khô ổn.', 'Khách mới: đừng đẩy Trophy nếu họ chưa từng đứng peg.', 'https://images.unsplash.com/photo-1591637333184-19aa84b3e01f?auto=format&fit=crop&w=1400&q=80', 'Khoa', '2026-02-08'),
  ('ps-27', 'blog', 'mua-dem', 'Chạy mưa đêm về', 'Đèn tốt. Áo mưa vẫn quan trọng hơn mọi option.', 'Rain mode làm ga dễ chịu. Phanh không bất ngờ.', 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1400&q=80', 'Trang', '2026-01-25'),
  ('ps-28', 'blog', 'so-voi-xe-cu', 'Đổi từ GS cũ sang R 1300', 'Nhẹ đầu xe hơn khi phanh. Máy êm dưới 4.000 vòng.', 'Khách đang đi GS cũ hay hỏi đúng câu này. Cho họ chạy thử 15 phút.', 'https://images.unsplash.com/photo-1449426468159-d96dbf08f19f?auto=format&fit=crop&w=1400&q=80', 'Quang', '2026-01-12'),
  ('ps-29', 'blog', 'ngoi-thu-showroom', 'Ghi chú sau một buổi cho khách ngồi thử', 'Ba người, hai người chọn yên thấp. Một người không với đất bằng cả hai chân vẫn mua.', 'Đừng đo chiều cao khách. Cứ mời ngồi.', 'https://images.unsplash.com/photo-1558980664-10e7170b5df2?auto=format&fit=crop&w=1400&q=80', 'Lan', '2025-12-30')
